(() => {
'use strict';
const $=s=>document.querySelector(s),c=window.HVT,b=window.HVTBranding;
let preview=false,user=null,loaded=null,token=0;const objects=new Map();
const labels={hero:'Ảnh trang chủ',logo:'Logo',favicon:'Favicon'};
$('#brandingCards').innerHTML=Object.entries(labels).map(([key,title])=>`<section class="panel branding-card"><h3>${title}</h3><div class="brand-image-preview brand-preview-${key}"><img id="${key}BrandPreview" alt="Xem trước ${title}" ${key==='logo'?'hidden':''}><span id="${key}BrandPlaceholder" ${key==='logo'?'':'hidden'}>❋</span></div><label>Chọn ảnh từ thiết bị<input type="file" name="${key}_file" accept="image/png,image/jpeg,image/webp"></label><p class="hint">PNG, JPG, WebP · tối đa 5 MB${key==='favicon'?' · tự chuyển thành PNG vuông':''}.</p><label>Hoặc URL ảnh HTTPS<input name="${key}_url" type="url" placeholder="https://…"></label><label class="check"><input name="${key}_reset" type="checkbox"> Dùng lại mặc định</label></section>`).join('');
const form=$('#brandingForm');
function status(text,error=false){$('#brandingStatus').textContent=text;$('#brandingStatus').classList.toggle('error',error)}
function show(key,src){const img=$('#'+key+'BrandPreview'),placeholder=$('#'+key+'BrandPlaceholder');img.hidden=!src;placeholder.hidden=!!src;if(src){img.src=src;img.onerror=()=>{img.hidden=true;placeholder.hidden=false}}else img.removeAttribute('src');if(key==='hero')img.style.objectPosition=form.elements.hero_position.value+' center'}
function clearObjects(){objects.forEach(value=>URL.revokeObjectURL(value));objects.clear()}
async function populate(){const sequence=++token;clearObjects();form.reset();loaded=null;$('#saveBranding').disabled=true;try{if(!preview&&c.configured){const rows=await c.api('/rest/v1/site_branding?select=*&id=eq.1');if(sequence!==token)return;if(!rows?.length)throw Error('Chạy supabase/upgrade-pages-branding-members.sql để tạo cấu hình giao diện.');loaded=rows[0]}else loaded={};const resolved=b.resolve(loaded);for(const key of Object.keys(labels)){form.elements[key+'_url'].value=loaded[key+'_url']||'';show(key,resolved[key])}form.elements.hero_alt.value=resolved.hero_alt;form.elements.hero_position.value=resolved.hero_position;show('hero',resolved.hero);status(preview?'Xem trước giao diện. Đăng nhập và cài SQL để lưu thay đổi.':'Chọn ảnh mới hoặc nhập URL. Nhấn Lưu giao diện khi đã sẵn sàng.');$('#saveBranding').disabled=preview}catch(error){status('Chưa tải được cấu hình. '+error.message,true)}}
async function updatePreview(key){const file=form.elements[key+'_file'].files[0];if(objects.has(key)){URL.revokeObjectURL(objects.get(key));objects.delete(key)}if(file){try{const blob=await b.image(file,key);const object=URL.createObjectURL(blob);objects.set(key,object);show(key,object)}catch(error){status(error.message,true)}return}const reset=form.elements[key+'_reset'].checked;const src=reset?b.defaults[key]:c.https(form.elements[key+'_url'].value)?.href||b.resolve(loaded||{})[key];show(key,src)}
for(const key of Object.keys(labels)){form.elements[key+'_file'].onchange=()=>updatePreview(key);form.elements[key+'_url'].oninput=()=>updatePreview(key);form.elements[key+'_reset'].onchange=()=>updatePreview(key)}form.elements.hero_position.onchange=()=>updatePreview('hero');
$('#reloadBranding').onclick=populate;
form.onsubmit=async e=>{e.preventDefault();if(preview||!c.hasSession()||!loaded)return;const data=new FormData(form),record={hero_alt:data.get('hero_alt').trim(),hero_position:data.get('hero_position'),version:loaded.version+1,updated_at:new Date().toISOString()};$('#brandingFields').disabled=true;let attempted=false;const uploaded=[];try{status('Đang lưu giao diện…');for(const key of Object.keys(labels)){let path=loaded[key+'_path']||null,url=loaded[key+'_url']||null;const external=data.get(key+'_url').trim();if(external&&!c.https(external))throw Error('URL '+labels[key]+' phải bắt đầu bằng https://');if(data.has(key+'_reset')){path=null;url=null}else if(external){path=null;url=external}else if(!path)url=null;const file=data.get(key+'_file');if(file?.size){const blob=await b.image(file,key);path=await c.upload('branding',blob,key==='hero'?'webp':'png');uploaded.push(path);url=null}record[key+'_path']=path;record[key+'_url']=url}attempted=true;const result=await c.api('/rest/v1/site_branding?id=eq.1&version=eq.'+loaded.version,{method:'PATCH',headers:{'Content-Type':'application/json',Prefer:'return=representation'},body:JSON.stringify(record)});if(!result?.length)throw Error('Cấu hình đã được thay đổi ở phiên khác. Nhấn Tải lại cấu hình trước khi lưu.');loaded=result[0];b.apply(loaded);await populate();status('Đã lưu giao diện. Trang chủ, logo và favicon sẽ cập nhật cho người xem khi tải trang.')}catch(error){if(!attempted&&uploaded.length){try{await c.removeFiles('branding',uploaded)}catch{}}status(error.message,true)}finally{$('#brandingFields').disabled=false;$('#saveBranding').disabled=preview||!loaded}};
function activate(name){document.querySelectorAll('[data-admin-panel]').forEach(panel=>panel.hidden=panel.dataset.adminPanel!==name);document.querySelectorAll('[data-admin-tab]').forEach(btn=>{btn.classList.toggle('active',btn.dataset.adminTab===name);btn.setAttribute('aria-selected',String(btn.dataset.adminTab===name))});if(name==='branding')populate();if(name==='members')window.HVTMembers.open({preview,user});if(name==='posts')window.HVTPosts?.open({preview,user})}
document.querySelectorAll('[data-admin-tab]').forEach(btn=>btn.onclick=()=>activate(btn.dataset.adminTab));
window.HVTAdminTools={setSession(next){preview=!!next.preview;user=next.user||null;window.HVTMembers.reset();activate('library')},lock(){window.HVTPosts?.lock();window.HVTMembers.reset();$('#memberForm').reset();clearObjects()},activate};
})();
